"use strict";

const {randomUUID} = require("crypto");

module.exports = function(RED) {
    function messageSource(source) {
        return typeof source === "string" && /^msg(?:\.[a-z][a-z0-9_]*)+$/i.test(source) &&
            !source.split(".").some(part => part === "__proto__" || part === "constructor" || part === "prototype");
    }

    function parseFields(config) {
        const fields = JSON.parse(config.fields || "[]");
        if (!Array.isArray(fields) || fields.length < 1 || fields.length > 10) {
            throw new Error("Slack form needs 1 to 10 fields");
        }
        const names = new Set();
        for (const field of fields) {
            if (!field || typeof field.name !== "string" || !/^[a-z][a-z0-9_]{0,49}$/i.test(field.name) ||
                    names.has(field.name) || typeof field.label !== "string" || !field.label.trim() || field.label.length > 200) {
                throw new Error("Invalid Slack form field");
            }
            field.type = field.type || "text";
            if (field.type === "select") {
                if (field.source !== "static" && !messageSource(field.source)) {
                    throw new Error("Unsupported Slack form options source");
                }
                if (field.source === "static" && (!Array.isArray(field.options) || field.options.length < 1 || field.options.length > 100 ||
                        field.options.some(option => !option || typeof option.label !== "string" || typeof option.value !== "string" ||
                            !option.label.trim() || !option.value || option.label.length > 75 || option.value.length > 150))) {
                    throw new Error("Invalid static Slack form options");
                }
            } else if (field.type !== "text") {
                throw new Error("Unsupported Slack form field type");
            }
            names.add(field.name);
        }
        if (fields.some(field => field.dependsOn && !fields.some(other => other.name === field.dependsOn && other.type === "select"))) {
            throw new Error("Slack form dependency must refer to another select field");
        }
        return fields;
    }

    function parseMetadata(view) {
        try {
            return JSON.parse(view.private_metadata);
        } catch (error) {
            return null;
        }
    }

    function asOption(item) {
        if (!item || typeof item.label !== "string" || typeof item.value !== "string" ||
                !item.label.trim() || !item.value || item.value.length > 150) {
            return null;
        }
        return {text: {type: "plain_text", text: item.label.slice(0, 75)}, value: item.value};
    }

    function SlackFormFlow(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        const callbackId = "nrflow_" + node.id;
        const snapshots = new Map();
        let fields;
        let closed = false;
        node.socketId = null;

        try {
            fields = parseFields(config);
            if (!/^\/[a-z0-9_-]+$/i.test(config.command || "") ||
                    typeof config.title !== "string" || !config.title.trim() || config.title.length > 24) {
                throw new Error("Invalid Slack form command or title");
            }
        } catch (error) {
            node.status({fill: "red", shape: "ring", text: "invalid form"});
            node.error("Invalid Slack form configuration");
            return;
        }

        function actionId(field) {
            return field.type === "select" ? callbackId + "_" + field.name : "value";
        }

        function selectedValues(view, metadata) {
            const values = Object.assign({}, metadata.selected);
            const state = view && view.state && view.state.values;
            if (state) {
                for (const field of fields) {
                    const input = state[field.name] && state[field.name][actionId(field)];
                    const value = field.type === "select" ? input && input.selected_option && input.selected_option.value : input && input.value;
                    if (typeof value === "string") {
                        values[field.name] = value;
                    } else if (input) {
                        delete values[field.name];
                    }
                }
            }
            return values;
        }

        function staticOptions(field) {
            return field.options.map(asOption).filter(Boolean);
        }

        function sourceOptions(field, values, metadata) {
            const snapshot = snapshots.get(metadata.snapshotId);
            if (!snapshot || snapshot.user !== metadata.user || snapshot.expires < Date.now()) {
                return [];
            }
            const data = snapshot.fields[field.name];
            const name = values[field.dependsOn];
            let selected;
            if (Array.isArray(data)) {
                selected = data;
            } else if (data && Object.prototype.hasOwnProperty.call(data, name)) {
                selected = data[name];
            }
            return Array.isArray(selected) ? selected.map(item =>
                asOption(typeof item === "string" ? {label: item, value: item} : item)).filter(Boolean) : [];
        }

        function captureSources(message) {
            const data = {};
            for (const field of fields.filter(item => item.type === "select" && messageSource(item.source))) {
                const value = RED.util.getMessageProperty(message, field.source.slice(4));
                if (!Array.isArray(value) && (!value || typeof value !== "object" || Array.isArray(value) ||
                        Object.values(value).some(item => !Array.isArray(item)))) {
                    throw new Error("Slack form source " + field.source + " must be an array or a map of arrays");
                }
                if (JSON.stringify(value).length > 1000000) {
                    throw new Error("Slack form source is too large");
                }
                data[field.name] = structuredClone(value);
            }
            if (Object.keys(data).length === 0) {
                return null;
            }
            const id = randomUUID();
            const timer = setTimeout(() => snapshots.delete(id), 30 * 60 * 1000);
            timer.unref();
            snapshots.set(id, {user: message.slack.user, fields: data, timer, expires: Date.now() + 30 * 60 * 1000});
            return id;
        }

        function sanitizedOptions(options, query) {
            if (!Array.isArray(options)) {
                return [];
            }
            const needle = (query || "").toLowerCase();
            return options.map(asOption).filter(item => item && item.text.text.toLowerCase().includes(needle)).slice(0, 100);
        }

        function buildView(metadata, values = {}) {
            const selected = Object.assign({}, values);
            const blocks = fields.map(field => {
                let element;
                if (field.type === "select") {
                    element = {
                        type: field.source === "static" ? "static_select" : "external_select",
                        action_id: actionId(field),
                        placeholder: {type: "plain_text", text: "Select " + field.label.slice(0, 140)}
                    };
                    if (field.source === "static") {
                        element.options = staticOptions(field);
                    } else {
                        element.min_query_length = 0;
                    }
                    const initial = selected[field.name] || field.default;
                    const available = field.source === "static" ? element.options : sourceOptions(field, selected, metadata);
                    const option = available.find(item => item.value === initial);
                    if (option) {
                        element.initial_option = option;
                        selected[field.name] = option.value;
                    }
                } else {
                    element = {type: "plain_text_input", action_id: "value", multiline: field.multiline === true};
                    if (typeof selected[field.name] === "string") {
                        element.initial_value = selected[field.name];
                    }
                }
                return {
                    type: "input", block_id: field.name,
                    optional: field.required === false,
                    dispatch_action: field.type === "select" && fields.some(other => other.dependsOn === field.name),
                    label: {type: "plain_text", text: field.label}, element
                };
            });
            return {
                type: "modal", callback_id: callbackId,
                title: {type: "plain_text", text: config.title},
                submit: {type: "plain_text", text: "Send"},
                private_metadata: JSON.stringify(Object.assign({}, metadata, {selected})),
                blocks
            };
        }

        node.handleOptions = async function({ack, options}) {
            const metadata = options && options.view && parseMetadata(options.view);
            const field = fields.find(item => actionId(item) === (options && options.action_id));
            if (closed || !metadata || metadata.formId !== node.id || metadata.user !== (options.user && options.user.id) ||
                    !field || field.type !== "select") {
                await ack({options: []});
                return;
            }
            const values = selectedValues(options.view, metadata);
            const available = field.source === "static" ? staticOptions(field) : sourceOptions(field, values, metadata);
            const candidates = sanitizedOptions(available.map(item => ({label: item.text.text, value: item.value})), options.value);
            await ack({options: candidates});
        };

        node.handleAction = async function({action, body, client}) {
            const metadata = body && body.view && parseMetadata(body.view);
            const field = fields.find(item => actionId(item) === (action && action.action_id));
            if (closed || !metadata || metadata.user !== (body.user && body.user.id) || !field ||
                    !fields.some(item => item.dependsOn === field.name) || !action.selected_option) {
                return;
            }
            const values = selectedValues(body.view, metadata);
            values[field.name] = action.selected_option.value;
            for (const dependent of fields.filter(item => item.dependsOn === field.name)) {
                delete values[dependent.name];
            }
            try {
                await client.views.update({view_id: body.view.id, hash: body.view.hash, view: buildView(metadata, values)});
            } catch (error) {
                node.warn("Slack form could not update dependent fields");
            }
        };

        node.handleSubmission = async function({ack, body, view}) {
            const metadata = view && parseMetadata(view);
            if (closed || !metadata || metadata.formId !== node.id || metadata.user !== (body.user && body.user.id)) {
                await ack();
                return;
            }
            const values = selectedValues(view, metadata);
            const errors = {};
            for (const field of fields) {
                if (field.required !== false && (typeof values[field.name] !== "string" || !values[field.name].trim())) {
                    errors[field.name] = "Required";
                }
            }
            const selectedFields = fields.filter(field => field.type === "select" && values[field.name]);
            const verified = selectedFields.map(field => {
                const available = field.source === "static" ? staticOptions(field) : sourceOptions(field, values, metadata);
                return {field, valid: available.some(item => item.value === values[field.name])};
            });
            for (const result of verified) {
                if (!result.valid) {
                    errors[result.field.name] = "Select a valid option";
                }
            }
            if (Object.keys(errors).length > 0) {
                await ack({response_action: "errors", errors});
                return;
            }
            await ack();
            if (metadata.snapshotId) {
                const snapshot = snapshots.get(metadata.snapshotId);
                if (snapshot) {
                    clearTimeout(snapshot.timer);
                    snapshots.delete(metadata.snapshotId);
                }
            }
            const payload = {};
            for (const field of fields) {
                payload[field.name] = typeof values[field.name] === "string" ? values[field.name] : "";
            }
            node.send({payload, topic: metadata.channel, slack: {
                eventType: "form_submission", channel: metadata.channel,
                user: metadata.user, command: metadata.command, viewId: view.id
            }});
        };

        node.on("input", async function(msg, send, done) {
            if (!msg.slack || msg.slack.eventType !== "slash_command" || msg.slack.command !== config.command) {
                done();
                return;
            }
            let snapshotId;
            try {
                const socket = RED.nodes.getNode(msg.slack.socketId);
                if (!socket || typeof socket.openForm !== "function") {
                    throw new Error("Slack Socket node is unavailable");
                }
                if (node.socketId && node.socketId !== socket.id) {
                    throw new Error("Slack form cannot use multiple Socket nodes");
                }
                node.socketId = socket.id;
                snapshotId = captureSources(msg);
                const metadata = {formId: node.id, user: msg.slack.user, channel: msg.slack.channel, command: config.command, snapshotId};
                const result = await socket.openForm(msg.slack.interactionId, node.id, buildView(metadata));
                if (!result.ok) {
                    const failure = new Error("Slack form could not open");
                    failure.data = result;
                    throw failure;
                }
                done();
            } catch (error) {
                if (snapshotId) {
                    const snapshot = snapshots.get(snapshotId);
                    if (snapshot) {
                        clearTimeout(snapshot.timer);
                        snapshots.delete(snapshotId);
                    }
                }
                node.status({fill: "red", shape: "ring", text: "form unavailable"});
                const slackCode = error.data && error.data.error;
                const reason = /^Slack form (source |interaction (?:expired|is invalid)$)/.test(error.message) ? error.message :
                    typeof slackCode === "string" && /^[a-z][a-z0-9_]*$/i.test(slackCode) ? "Slack form could not open: " + slackCode :
                        "Slack form could not open";
                done(new Error(reason));
            }
        });

        node.on("close", function() {
            closed = true;
            for (const snapshot of snapshots.values()) {
                clearTimeout(snapshot.timer);
            }
            snapshots.clear();
        });
    }

    RED.nodes.registerType("slack form flow", SlackFormFlow);
};
